{"path": "api/quiet_hours_test.go", "old": "", "new": "package api_test

import (
	"net/http"
	"testing"
)

// Quiet hours must be real times of day; "24:00" used to be stored and then
// crashed GET /v1/me/digest in notify.QuietHours.
func TestPrefsRejectOutOfRangeQuietHours(t *testing.T) {
	c := newClient(t)
	for _, body := range []string{
		`{"quiet_from":"24:00","quiet_to":"07:00"}`,
		`{"quiet_from":"22:00","quiet_to":"24:00"}`,
		`{"quiet_from":"99:99","quiet_to":"07:00"}`,
		`{"quiet_from":"12:60","quiet_to":"07:00"}`,
	} {
		if code := c.do("tok-ana", http.MethodPut, "/v1/me/prefs", body, nil); code != http.StatusBadRequest {
			t.Errorf("prefs %s: status %d, want 400", body, code)
		}
	}
	if code := c.do("tok-ana", http.MethodPut, "/v1/me/prefs", `{"quiet_from":"7:05","quiet_to":"23:59"}`, nil); code != http.StatusOK {
		t.Errorf("valid quiet hours: status %d, want 200", code)
	}
}
"}

